for (const v of VECTORS) {
  test(`pi redactor hardening: ${v.name}`, () => {
    const text = v.input.join("");
    const out = redact(text);
    if (v.same) {
      assert.equal(out, text);
      return;
    }
    for (const needle of v.absent ?? []) assert.ok(!out.includes(needle), `${needle} survived: ${out}`);
    for (const needle of v.present ?? []) assert.ok(out.includes(needle), `${needle} was wrongly removed: ${out}`);
  });
}

// F6: a 200 KB adversarial input must redact in under one second. The old JWT
// pattern took about 8 s at 100 KB.
const SPEED = [["eyJ x 200KB","eyJ",66666],["eyJ then a long run","",1],["eyJ run with dots","eyJaaaaaaaaaaaa.",12500],["hyphen run","a-",100000],["key words","key-",50000],["key= repeated","key=",50000],["password: repeated","password: ",20000],["Bearer repeated","Bearer ",30000],["unclosed quote assignments","TOKEN=\"",30000],["bare key chain (no recursion)","key:",50000],["bare key chain with values","key: x ",28000],["bare key then assignment chain","key: API_KEY=v ",13000],["secret names with a long tail","SECRET_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx ",2500]];
for (const [name, unit, count] of SPEED) {
  test(`pi redactor stays linear: ${name}`, () => {
    const input = unit.repeat(count);
    // Best of 3 so a busy machine does not fail the test; a quadratic pattern is slow every time.
    let secs = Infinity;
    for (let run = 0; run < 3 && secs >= 1; run++) {
      const t0 = performance.now();
      redact(input);
      secs = Math.min(secs, (performance.now() - t0) / 1000);
    }
    assert.ok(secs < 1, `${name} took ${secs}s`);
  });
}

test("pi redactor still catches a real-shaped JWT after the linear fix", () => {
  const jwt = ["eyJZmFrZUhkcjEyMyJ9", ".eyJGYWtlUGF5bG9hZCI6MX0", ".ZmFrZVNpZ25hdHVyZUFCQ0RF"].join("");
  for (const text of [`auth header ${jwt} end`, `curl -H "x-session: ${jwt}"`, `{"jwt":"${jwt}"}`]) {
    const out = redact(text);
    assert.ok(!out.includes(jwt.slice(0, 20)), `JWT survived: ${out}`);
    assert.ok(!out.includes(jwt.slice(-12)), `JWT tail survived: ${out}`);
  }
});
